// Title: Export Excel worksheet to HTML with cell comments and TableCssId‑prefixed CSS using Aspose.Cells for .NET
// Common Searches: Aspose.Cells C# export worksheet to HTML including cell comments | How to set TableCssId for HTML tables generated by Aspose.Cells | Preserve HTML formatted comment text when saving Excel as HTML with Aspose.Cells | Save only the active sheet to HTML with embedded images using Aspose.Cells | Apply custom CSS class to tables in HTML output from Aspose.Cells
// Tags: Aspose.Cells HtmlSaveOptions TableCssId | export cell comments to HTML using Aspose.Cells | custom CSS class for Aspose.Cells HTML tables | HTML formatted comment content Aspose.Cells | save workbook as HTML with embedded images Aspose.Cells

using System;
using System.IO;
using Aspose.Cells;
using Aspose.Cells.Tables;

namespace AsposeCellsHtmlExportWithComments
{
    // The example loads or creates an Excel workbook, adds a ListObject table, inserts a cell comment with plain‑text and HTML markup, configures HtmlSaveOptions (TableCssId = "myTable", ExportActiveWorksheetOnly, ExportImagesAsBase64), and saves the active worksheet as an HTML file. The generated HTML includes the comment content and applies the custom TableCssId‑prefixed CSS class to the table.
    class Program
    {
        static void Main(string[] args)
        {
            try
            {
                // Input and output file paths.
                string inputPath = "InputWorkbook.xlsx";
                string outputPath = "ExportedWithComments.html";

                // Load existing workbook or create a new one.
                Workbook workbook;
                if (File.Exists(inputPath))
                {
                    Console.WriteLine($"Loading workbook from '{inputPath}'.");
                    workbook = new Workbook(inputPath);
                }
                else
                {
                    Console.WriteLine("Input file not found. Creating a new workbook.");
                    workbook = new Workbook();
                    Worksheet ws = workbook.Worksheets[0];
                    ws.Name = "Data";

                    // Populate sample data.
                    ws.Cells["A1"].PutValue("ID");
                    ws.Cells["B1"].PutValue("Name");
                    ws.Cells["A2"].PutValue(1);
                    ws.Cells["B2"].PutValue("Alice");
                    ws.Cells["A3"].PutValue(2);
                    ws.Cells["B3"].PutValue("Bob");
                    ws.Cells["A4"].PutValue(3);
                    ws.Cells["B4"].PutValue("Charlie");

                    // Create a table over the data range (hasHeaders = true).
                    int tableIndex = ws.ListObjects.Add(0, 0, 4, 2, true);
                    ListObject table = ws.ListObjects[tableIndex];
                    // The Name property may not be available in older versions; it is optional.
                    table.ShowHeaderRow = true;
                    table.ShowTableStyleFirstColumn = false;
                    table.ShowTableStyleLastColumn = false;
                    table.ShowTableStyleRowStripes = true;
                    table.ShowTableStyleColumnStripes = false;
                    table.TableStyleType = TableStyleType.TableStyleMedium9;

                    // Add a comment with HTML content.
                    int commentIndex = ws.Comments.Add("B2");
                    Comment comment = ws.Comments[commentIndex];
                    comment.Author = "Admin";
                    comment.Note = "This is a plain‑text comment.";
                    comment.HtmlNote = "<b>Important:</b> Verify the employee name.";

                    // Autofit columns for better appearance.
                    ws.AutoFitColumns();
                }

                // Configure HTML save options.
                HtmlSaveOptions saveOptions = new HtmlSaveOptions
                {
                    TableCssId = "myTable",                 // Prefix CSS class for the table.
                    ExportActiveWorksheetOnly = true,       // Export only the active sheet.
                    ExportImagesAsBase64 = true             // Embed images as Base64.
                    // Comments are exported by default.
                };

                // Save the workbook as HTML.
                Console.WriteLine($"Saving HTML to '{outputPath}'.");
                workbook.Save(outputPath, saveOptions);

                // Verify the output.
                if (File.Exists(outputPath))
                {
                    string htmlContent = File.ReadAllText(outputPath);
                    bool hasComment = htmlContent.Contains("This is a plain‑text comment.") ||
                                      htmlContent.Contains("<b>Important:</b>");
                    bool hasTableCssId = htmlContent.Contains("class=\"myTable");
                    Console.WriteLine($"HTML export completed. Comment present: {hasComment}, Table CSS ID applied: {hasTableCssId}");
                }
                else
                {
                    Console.WriteLine("Failed to create the HTML file.");
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("An error occurred during processing:");
                Console.WriteLine(ex.Message);
                Console.WriteLine(ex.StackTrace);
            }
        }
    }
}
